data.inputSchema:
{
  "title": "input parameters",
  "type": "object",
  "schemaVersion": 1,
  "description": "Turn Instagram videos into clean, structured transcripts with ease.\nThis API helps you extract spoken content (auto-generated transcripts) from public Instagram videos — designed for developers, data teams, and AI agents that need text, not just media.",
  "properties": {
    "videoUrl": {
      "title": "The URL of the instagram",
      "type": "string",
      "description": "The URL of the instagram you want to get the data from.",
      "editor": "textfield",
      "prefill": "https://www.instagram.com/p/DULBkEngpxg"
    },
    "bulkUrls": {
      "title": "The URLs of the instagram",
      "type": "array",
      "description": "🚀 BULK PROCESSING: Extract transcripts from multiple Instagram videos at once.\n✨ Perfect for content creators, marketers & social media analysts\n💰 TIER-BASED LIMITS:\n• FREE users: Up to 5 URLs per run\n• PAID users: Unlimited URLs",
      "editor": "stringList",
      "prefill": []
    },
    "usernames": {
      "title": "The usernames of the instagram",
      "type": "array",
      "description": "The usernames of the instagram you want to get the data from.",
      "editor": "stringList",
      "prefill": [
        "bbcnews"
      ],
      "sectionCaption": "Channel Scrape",
      "sectionDescription": "Automatically scrape multiple reels from an Instagram profile"
    },
    "resultsLimit": {
      "title": "The results limit",
      "type": "integer",
      "description": "The maximum number of results to return.",
      "editor": "number",
      "prefill": 12
    },
    "onlyPostsNewerThan": {
      "title": "Scrape reels newer than",
      "type": "string",
      "editor": "datepicker",
      "dateType": "absoluteOrRelative",
      "description": "Scrape reels from the provided date up to the present. Supported formats include YYYY-MM-DD, full ISO timestamps (e.g. 2025-09-23T10:02:01), or relative time such as 1 day, 2 weeks, or 3 months. All times are evaluated in UTC.",
      "pattern": "^(\\d{4})-(0[1-9]|1[0-2])-(0[1-9]|[12]\\d|3[01])$|^(\\d+)\\s*(day|week|month|year)s?$"
    },
    "skipPinnedPosts": {
      "title": " Skip pinned reels",
      "type": "boolean",
      "description": "Enable this option if you want to exclude pinned reels from the overall results.",
      "editor": "checkbox",
      "prefill": false
    },
    "includeSharesCount": {
      "title": "Include Shares Count",
      "type": "boolean",
      "description": "Whether to include the shares count in the results.Available for paying users only. Upgrade to the Starter plan to unlock it.",
      "editor": "checkbox",
      "prefill": false
    }
  },
  "required": []
}
